export const meta = {
  name: 'read-two-files',
  description: 'Fan out two agents in parallel to read a.txt and b.txt and return their contents',
  phases: [{ title: 'Read', detail: 'read a.txt and b.txt' }],
}

phase('Read')

const results = await parallel([
  () => agent('Read the file at /p/a.txt and return its exact content as your final output. Do not add any commentary.', { label: 'read:a.txt', phase: 'Read' }),
  () => agent('Read the file at /p/b.txt and return its exact content as your final output. Do not add any commentary.', { label: 'read:b.txt', phase: 'Read' }),
])

return {
  a: results[0],
  b: results[1],
}

